// https://codesandbox.io/p/sandbox/e662p3?file=%2Fpackage.json%3A31%2C5
export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.clearColor = BABYLON.Color4.FromHexString("#15151aff");
  scene.useRightHandedSystem = true;

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.23, -0.63, 0.06));
  camera.alpha = 4.989;
  camera.beta = 1.428;
  camera.lowerBetaLimit = Math.PI / 2.2;
  camera.upperBetaLimit = Math.PI / 2.2;
  camera.radius = 3.98;
  camera.lowrRadiusLimit = 3.5;
  camera.upperRadiusLimit = 7.8;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);
  camera.useAutoRotationBehavior = true;

  // const viewerLayer = 0x10000000;
  const probeLayer = 0x20000000;

  // camera.layerMask = viewerLayer;

  var light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.5;

  var pointLight = new BABYLON.PointLight("pointLight", new BABYLON.Vector3(0, 2, -4.93), scene);
  // pointLight.diffuse = BABYLON.Color3.Red();
  pointLight.diffuse = BABYLON.Color3.FromHexString("#009DFF");
  pointLight.intensity = 33;

  const probe = new BABYLON.ReflectionProbe("envProbe", 512, scene);
  scene.environmentTexture = probe.cubeTexture;
  scene.environmentIntensity = 1.0;

  const carEngineClip = new BABYLON.Sound("gunshot", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/Sounds/car ignition.mp3", scene);
  carEngineClip.setVolume(1);

  function createLight(position, rotation, color, name, scene) {
    const box = BABYLON.MeshBuilder.CreateBox("box" + name, { width: 6, height: 6, depth: 0.01 });
    const lightMaterial = new BABYLON.StandardMaterial();
    lightMaterial.disableLighting = true;
    lightMaterial.emissiveColor = color;
    box.material = lightMaterial;

    box.layerMask = 0x20000000;

    box.position = position;
    box.rotation = rotation;

    var light = new BABYLON.RectAreaLight("light" + name, new BABYLON.Vector3(0, 0, 0), 6, 6, scene);
    light.parent = box;
    light.specular = color;
    light.diffuse = color;

    light.intensity = 0.7;
  }

  function createLightformer(name, position, rotation, scale, color = new BABYLON.Color3(1, 1, 1), intensity = 1) {
    const plane = BABYLON.MeshBuilder.CreatePlane(name, { size: 1 }, scene);
    plane.scaling = scale;
    plane.position = position;
    plane.rotation = rotation;

    const mat = new BABYLON.StandardMaterial(name + "Mat", scene);
    mat.emissiveColor = color.scale(intensity);
    mat.backFaceCulling = false;
    plane.material = mat;

    probe.renderList?.push(plane);
    plane.layerMask = probeLayer;

    return plane;
  }

  for (let z = -9; z <= 9; z += 3) {
    createLightformer(
      "ceiling" + z,
      new BABYLON.Vector3(0, 4, z),
      new BABYLON.Vector3(Math.PI / 2, 0, 0),
      new BABYLON.Vector3(10, 1, 1),
      BABYLON.Color3.White(),
      2
    );
  }

  createLightformer(
    "sideLeft",
    new BABYLON.Vector3(-50, 2, 0),
    new BABYLON.Vector3(0, Math.PI / 2, 0),
    new BABYLON.Vector3(100, 2, 1),
    BABYLON.Color3.White(),
    2
  );

  createLightformer(
    "sideRight",
    new BABYLON.Vector3(50, 2, 0),
    new BABYLON.Vector3(0, -Math.PI / 2, 0),
    new BABYLON.Vector3(100, 2, 1),
    BABYLON.Color3.White(),
    2
  );

  const keyLight = BABYLON.MeshBuilder.CreatePlane(
    "key",
    {
      size: 1,
    },
    scene
  );
  keyLight.position = new BABYLON.Vector3(3.19, 4.31, 3.14);
  keyLight.rotation = new BABYLON.Vector3(BABYLON.Tools.ToRadians(-55.09), BABYLON.Tools.ToRadians(60.52), BABYLON.Tools.ToRadians(175.7));
  keyLight.scaling = new BABYLON.Vector3(4, 1, 4);
  keyLight.layerMask = probeLayer;

  const redMat = new BABYLON.StandardMaterial("redMat", scene);
  // redMat.emissiveColor = BABYLON.Color3.Red();
  redMat.emissiveColor = BABYLON.Color3.FromHexString("#2D9CFF");

  // createLight(new BABYLON.Vector3(-3, 1.22, -0.73), new BABYLON.Vector3(BABYLON.Tools.ToRadians(-39.8), BABYLON.Tools.ToRadians(-125), BABYLON.Tools.ToRadians(3.2)),
  // BABYLON.Color3.Red(), "light1" ,scene);
  createLight(
    new BABYLON.Vector3(2, 3, -1),
    new BABYLON.Vector3(5.976007358828584, 1.5969762655748114),
    new BABYLON.Color3(0.04, 0.55, 0.75).toLinearSpace(),
    "light1",
    scene
  );
  createLight(
    new BABYLON.Vector3(-3, 3, 10),
    new BABYLON.Vector3(5.681046715241543, 0, 0),
    new BABYLON.Color3(0.97, 0.4, 0.22).toLinearSpace(),
    "light2",
    scene
  );
  createLight(
    new BABYLON.Vector3(-10, 3, -1),
    new BABYLON.Vector3(5.68, -1.59, 0),
    new BABYLON.Color3(0.04, 0.75, 0.04).toLinearSpace(),
    "light3",
    scene
  );

  redMat.disableLighting = true;
  keyLight.material = redMat;

  probe.renderList?.push(keyLight);

  const shadowPlane = BABYLON.MeshBuilder.CreateGround(
    "shadowPlane",
    {
      width: 15,
      height: 15,
    },
    scene
  );
  shadowPlane.position = new BABYLON.Vector3(0, -1.19, 0);
  // shadowPlane.layerMask = viewerLayer;

  const shadowMat = new BABYLON.PBRMaterial("shadowMat", scene);
  shadowMat.albedoColor = new BABYLON.Color3(0, 0, 0);
  shadowMat.alpha = 0.65;
  shadowMat.disableLighting = true;
  shadowPlane.material = shadowMat;
  shadowPlane.material.reflectionTexture = new BABYLON.MirrorTexture("mirror", { ratio: 0.5 }, scene, true);
  shadowPlane.material.reflectionTexture.mirrorPlane = new BABYLON.Plane(0, -1.0, 0, -1.05);
  shadowPlane.material.reflectionTexture.level = 1.0;
  shadowPlane.material.reflectionTexture.adaptiveBlurKernel = 32;

  const ring1 = BABYLON.MeshBuilder.CreateTorus(
    "rect",
    {
      diameter: 1 + 0.9,
      thickness: 0.15,
      tessellation: 4,
    },
    scene
  );
  ring1.scaling = new BABYLON.Vector3(1, 0.1, 1);
  ring1.position = new BABYLON.Vector3(1.5, -1.161, -0.5);

  const mat1 = new BABYLON.PBRMaterial("mat1", scene);
  // mat1.emissiveColor = BABYLON.Color3.FromHexString("#404B67").toLinearSpace();
  mat1.emissiveColor = BABYLON.Color3.FromHexString("#404B67").toLinearSpace();
  mat1.roughness = 0.75;
  ring1.material = mat1;

  const ring2 = BABYLON.MeshBuilder.CreateTorus(
    "tri",
    {
      diameter: 1 + 0.9,
      thickness: 0.25,
      tessellation: 3,
    },
    scene
  );
  ring2.scaling = new BABYLON.Vector3(1, 0.1, 1);
  ring2.position = new BABYLON.Vector3(-1, -1.161, 0);

  const mat2 = mat1.clone("mat2");
  ring2.material = mat2;

  var fileInput = document.createElement("input");
  fileInput.type = "file";
  fileInput.accept = ".glb";
  fileInput.style.display = "none";
  document.body.appendChild(fileInput);

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "koenigsegg_one.glb").then((result) => {
    const rootMesh = result.meshes[0];
    camera.setTarget(rootMesh.position.add(new BABYLON.Vector3(0.2, -0.63, 0)));
    camera.alpha = 4.989;
    camera.beta = 1.428;
    camera.radius = 3.98;

    engine.setHardwareScalingLevel(0.8);

    rootMesh.scaling.scaleInPlace(100);
    rootMesh.position.y = -1.13;
    rootMesh.rotation.y = Math.PI / 1.5;

    // for SSR
    shadowPlane.material.reflectionTexture.renderList = rootMesh.getChildMeshes();
    /*
                rootMesh.getChildMeshes().forEach((mesh) => {
                    if (mesh.name.startsWith("glass")) {
                        if (mesh.material) {
                            mesh.material.backFaceCulling = false;
                            mesh.material.transparencyMode = BABYLON.Material.MATERIAL_ALPHABLEND;
                            mesh.material.alpha = 0.5;
                        }
                    }
        
                    if (mesh.name === "silver_001_BreakDiscs_0" && mesh.material) {
                        mesh.material = mesh.material.clone("logoFix");
                        mesh.material.albedoColor = new BABYLON.Color3(0.85, 0.85, 0.85).toLinearSpace();
                    }
        
                    if (mesh.name === "yellow_WhiteCar_0") {
                        const newMat = new BABYLON.PBRMaterial("carPaint", scene);
                        newMat.metallic = 0.05;
                        newMat.roughness = 0.3;
                        newMat.clearCoat.isEnabled = true;
                        newMat.clearCoat.roughness = 0;
                        newMat.clearCoat.intensity = 1;
                        newMat.albedoColor = new BABYLON.Color3(0.07, 0.07, 0.07).toLinearSpace();
                        newMat.environmentIntensity = 0.75;
                        mesh.material = newMat;
                    }
        
                    if (mesh.material && mesh.material.name.includes("Chrome")) {
                        mesh.material.metallic = 1;
                        mesh.material.roughness = 0.5;
                        mesh.material.albedoColor = new BABYLON.Color3(0.2, 0.2, 0.2).toLinearSpace();
                    }
        
                    if (mesh.material && mesh.material.name.includes("BreakDiscs")) {
                        mesh.material.metallic = 0.2;
                        mesh.material.roughness = 0.2;
                        mesh.material.albedoColor = new BABYLON.Color3(0.4, 0.4, 0.4).toLinearSpace();
                    }
        
                    if (mesh.material && mesh.material.name.includes("TiresGum")) {
                        mesh.material.metallic = 0;
                        mesh.material.roughness = 0.4;
                        mesh.material.albedoColor = new BABYLON.Color3(0.1, 0.1, 0.1).toLinearSpace();
                    }
        
                    if (mesh.material && (mesh.material.name.includes("emitbrake"))) {
                        mesh.material.emissiveColor = new BABYLON.Color3(1, 0, 0).toLinearSpace();
                        mesh.material.emissiveIntensity = 3;
                    }
        
                    if(mesh.material.name.includes("LightsFrontLed")){
                        mesh.material.emissiveColor = BABYLON.Color3.FromHexString("#193654").toLinearSpace();
                        mesh.material.emissiveIntensity = 3;
                    }
                });
        */

    var taa = new BABYLON.TAARenderingPipeline("taa", scene);
    taa.disableOnCameraMove = false;
    taa.factor = 0.3;
    taa.msaaSamples = 8;
    taa.samples = 32;

    const pipeline = new BABYLON.DefaultRenderingPipeline("defaultPipeline", true, scene, [camera]);
    pipeline.samples = 4;
    pipeline.imageProcessingEnabled = false;
    // pipeline.imageProcessing.colorGradingEnabled = true;
    // pipeline.imageProcessing.colorGradingTexture = new BABYLON.ColorGradingTexture("textures/LateSunset.3dl", scene);

    pipeline.fxaaEnabled = true;

    pipeline.bloomEnabled = true;
    pipeline.bloomThreshold = 0.05;
    pipeline.bloomIntensity = 1.75;
    pipeline.bloomKernel = 64;
    pipeline.bloomWeight = 0.6;
    pipeline.bloomScale = 1;
    pipeline.glowLayerEnabled = true;
    pipeline.glowLayer.intensity = 4.5;
    pipeline.grainEnabled = true;
    pipeline.grain.intensity = 10;

    // const lutTexture = new BABYLON.ColorGradingTexture("F-6800-STD.cube", scene);
    // pipeline.imageProcessing.colorGradingEnabled = true;
    // pipeline.imageProcessing.colorGradingTexture = lutTexture;

    scene.onBeforeRenderObservable.add(() => {
      let alpha = camera.alpha % (Math.PI * 2);
      if (alpha < 0) alpha += Math.PI * 2;

      if (alpha >= 2.2 && alpha <= 2.95) {
        if (!carEngineClip.isPlaying) {
          carEngineClip.play();
        }
      } else {
        if (carEngineClip.isPlaying) {
          carEngineClip.stop();
        }
      }
    });
  });
  return scene;
}
